window.kbPageData["views/entry/k-f56483cb71c38b3e"] = {"key":"entry/k-f56483cb71c38b3e","state":{"route":"entry/k-f56483cb71c38b3e"},"node":{"id":"k-f56483cb71c38b3e","mode":"k","title":"有价证券持有人权利","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":["有价证券持有人权利可受证券种类限制"],"qs":["国考 2023 副省级 行测#10"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"有价证券持有人可以依证券种类及适用规则行使相应权利。不同类别证券的持有人可以享有不同的权利，行使权利也可能有条件。","review":{"definition":"有价证券持有人可以依证券种类及适用规则行使相应权利。不同类别证券的持有人可以享有不同的权利，行使权利也可能有条件。","explanation":"解析以优先股为例。优先股持有人可以在利润和剩余财产分配上享有优先权，同时其参与公司决策的表决权一般受限。分配优先与表决受限可以并存，足以支持C项所说的“不一定能行使有价证券的全部权利”。","references":[],"evidence":"有价证券的持有人不一定能行使有价证券的全部权利","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 副省级 行测#10":{"paper":"国考 2023 副省级 行测","n":10,"mod":"常识判断","src":["503793642e845de9795f.pdf",2],"asrc":["ecade1ff5af69283232e.pdf",4],"card":"6e3af3bf96b8071917d9b7de","links":[{"id":"k-f56483cb71c38b3e","role":"直接考查","why":"优先股体现了分配优先权与表决权受限可以并存。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-f56483cb71c38b3e":[["国考 2023 副省级 行测#10"]]}};
